patches.content:
// Override: the line above indexes the monitors ARRAY by Hyprland
// monitor ID, which only holds while IDs equal array positions. A
// Binding beats the original expression at runtime, insert-only.
Binding {
    target: root
    property: "biggestWindow"
    value: HyprlandData.biggestWindowForWorkspace(HyprlandData.monitors.find(m => m.id === root.monitor?.id)?.activeWorkspace?.id)
}
